// WWE '13: PlayStation button icons (launcher option "Button icons: PlayStation" -> WWE13_PS_PROMPTS=1).
// Hand-written; not generated by ReXGlue.
//
// The game draws its button prompts (A/B/X/Y, LB/RB, LT/RT, LS/RS, BACK/START) from DXT5 icon sheets: 256x512 in
// pac/menu/font*.pac (FNT2/FNTM/FNTO/FNTS) and 512x512 in pac/game2dHD.pac (GA2D/GI2D/GG2D/GS2D/GF2D BASE part 2). The parts are BPE-compressed; sub_82B29CA0(header, dest)
// unpacks one (uncompressed size = little-endian u32 at header + 12). After it returns, a DDS in the output that is
// exactly one of the game's icon sheets (size, format and a hash of its pixels) gets the patches from ps_prompts_data.h:
// our own PlayStation icons, blended in per 4x4 block and re-encoded as DXT5. No game file is changed; anything else is left alone.
#include <cstdint>
#include <cstdlib>
#include <cstring>

#include <rex/logging.h>
#include <rex/ppc/context.h>
#include "rex_compat.h"
#include "ps_prompts_data.h"

namespace {
bool Enabled() {
  static const bool on = [] { const char* e = std::getenv("WWE13_PS_PROMPTS"); return e && *e == '1'; }();
  return on;
}

uint32_t Le32(const uint8_t* p) { return uint32_t(p[0]) | uint32_t(p[1]) << 8 | uint32_t(p[2]) << 16 | uint32_t(p[3]) << 24; }

uint64_t Fnv(const uint8_t* p, uint32_t n) {
  uint64_t h = 0xcbf29ce484222325ull;
  for (uint32_t i = 0; i < n; ++i) h = (h ^ p[i]) * 0x100000001b3ull;
  return h;
}

// ---- DXT5 (BC3) block decode / encode, 16 RGBA pixels ----
void Rgb565(uint16_t v, int* c) {
  const int r = (v >> 11) & 31, g = (v >> 5) & 63, b = v & 31;
  c[0] = (r << 3) | (r >> 2); c[1] = (g << 2) | (g >> 4); c[2] = (b << 3) | (b >> 2);
}

void DecodeBlock(const uint8_t* b, uint8_t px[16][4]) {
  int a[8] = {b[0], b[1]};
  if (a[0] > a[1]) for (int i = 1; i < 7; ++i) a[i + 1] = ((7 - i) * a[0] + i * a[1]) / 7;
  else { for (int i = 1; i < 5; ++i) a[i + 1] = ((5 - i) * a[0] + i * a[1]) / 5; a[6] = 0; a[7] = 255; }
  uint64_t abits = 0;
  for (int i = 0; i < 6; ++i) abits |= uint64_t(b[2 + i]) << (8 * i);
  const uint16_t c0 = uint16_t(b[8] | b[9] << 8), c1 = uint16_t(b[10] | b[11] << 8);
  int c[4][3];
  Rgb565(c0, c[0]); Rgb565(c1, c[1]);
  for (int k = 0; k < 3; ++k) { c[2][k] = (2 * c[0][k] + c[1][k]) / 3; c[3][k] = (c[0][k] + 2 * c[1][k]) / 3; }
  const uint32_t cbits = Le32(b + 12);
  for (int i = 0; i < 16; ++i) {
    const int ci = (cbits >> (2 * i)) & 3;
    px[i][0] = uint8_t(c[ci][0]); px[i][1] = uint8_t(c[ci][1]); px[i][2] = uint8_t(c[ci][2]);
    px[i][3] = uint8_t(a[(abits >> (3 * i)) & 7]);
  }
}

uint16_t To565(const int* c) { return uint16_t((c[0] >> 3) << 11 | (c[1] >> 2) << 5 | (c[2] >> 3)); }

void EncodeBlock(const uint8_t px[16][4], uint8_t* b) {
  // Alpha: 8-level ramp between the block's max and min.
  int amax = 0, amin = 255;
  for (int i = 0; i < 16; ++i) { amax = px[i][3] > amax ? px[i][3] : amax; amin = px[i][3] < amin ? px[i][3] : amin; }
  if (amax == amin) { if (amax == 0) amax = 1; else amin = amax - 1; }
  int a[8] = {amax, amin};
  for (int i = 1; i < 7; ++i) a[i + 1] = ((7 - i) * amax + i * amin) / 7;
  uint64_t abits = 0;
  for (int i = 0; i < 16; ++i) {
    int best = 0, bd = 1 << 30;
    for (int k = 0; k < 8; ++k) { const int d = (px[i][3] - a[k]) * (px[i][3] - a[k]); if (d < bd) { bd = d; best = k; } }
    abits |= uint64_t(best) << (3 * i);
  }
  b[0] = uint8_t(amax); b[1] = uint8_t(amin);
  for (int i = 0; i < 6; ++i) b[2 + i] = uint8_t(abits >> (8 * i));
  // Colour: endpoints = the brightest and darkest visible pixels (by luma).
  int lo = -1, hi = -1, llo = 1 << 30, lhi = -1;
  for (int i = 0; i < 16; ++i) {
    if (px[i][3] < 16) continue;
    const int l = 2 * px[i][0] + 4 * px[i][1] + px[i][2];
    if (l < llo) { llo = l; lo = i; }
    if (l > lhi) { lhi = l; hi = i; }
  }
  if (lo < 0) { lo = hi = 0; }
  int e0[3] = {px[hi][0], px[hi][1], px[hi][2]}, e1[3] = {px[lo][0], px[lo][1], px[lo][2]};
  uint16_t v0 = To565(e0), v1 = To565(e1);
  if (v0 < v1) { const uint16_t t = v0; v0 = v1; v1 = t; }
  uint32_t cbits = 0;
  if (v0 == v1) {
    if (v0 > 0) --v1; else ++v0;  // keep 4-colour mode (c0 > c1)
  }
  int c[4][3];
  Rgb565(v0, c[0]); Rgb565(v1, c[1]);
  for (int k = 0; k < 3; ++k) { c[2][k] = (2 * c[0][k] + c[1][k]) / 3; c[3][k] = (c[0][k] + 2 * c[1][k]) / 3; }
  for (int i = 0; i < 16; ++i) {
    int best = 0, bd = 1 << 30;
    for (int k = 0; k < 4; ++k) {
      int d = 0;
      for (int j = 0; j < 3; ++j) d += (px[i][j] - c[k][j]) * (px[i][j] - c[k][j]);
      if (d < bd) { bd = d; best = k; }
    }
    cbits |= uint32_t(best) << (2 * i);
  }
  b[8] = uint8_t(v0); b[9] = uint8_t(v0 >> 8); b[10] = uint8_t(v1); b[11] = uint8_t(v1 >> 8);
  b[12] = uint8_t(cbits); b[13] = uint8_t(cbits >> 8); b[14] = uint8_t(cbits >> 16); b[15] = uint8_t(cbits >> 24);
}

void ApplyPatches(uint8_t* px, uint32_t sheet, uint32_t width) {
  const uint32_t pitch = width / 4;  // blocks per row
  for (const auto& p : wwe13_ps::kPatches) {
    if (p.sheet != sheet) continue;
    for (uint32_t by = 0; by < p.h / 4u; ++by) {
      for (uint32_t bx = 0; bx < p.w / 4u; ++bx) {
        uint8_t* block = px + (((p.y / 4u) + by) * pitch + (p.x / 4u) + bx) * 16;
        uint8_t pix[16][4];
        if (p.mode == 0) std::memset(pix, 0, sizeof(pix));
        else DecodeBlock(block, pix);
        for (int i = 0; i < 16; ++i) {
          const uint8_t* s = p.rgba + ((by * 4 + i / 4) * p.w + bx * 4 + i % 4) * 4;
          const int sa = s[3], da = pix[i][3];
          const int oa = sa + da * (255 - sa) / 255;
          if (oa == 0) { std::memset(pix[i], 0, 4); continue; }
          for (int k = 0; k < 3; ++k) pix[i][k] = uint8_t((s[k] * sa + pix[i][k] * da * (255 - sa) / 255) / oa);
          pix[i][3] = uint8_t(oa);
        }
        EncodeBlock(pix, block);
      }
    }
  }
}

void PatchSheets(uint8_t* out, uint32_t size, uint32_t guest) {
  static const uint8_t kMagic[] = {'D', 'D', 'S', ' ', 0x7c, 0, 0, 0};
  for (uint32_t i = 0; i + 128 <= size;) {
    const void* hit = memmem(out + i, size - i, kMagic, sizeof(kMagic));
    if (!hit) break;
    const uint32_t at = uint32_t(static_cast<const uint8_t*>(hit) - out);
    i = at + 4;
    const uint8_t* d = out + at;
    if (at + 128 > size || std::memcmp(d + 84, "DXT5", 4) != 0) continue;
    const uint32_t h = Le32(d + 12), w = Le32(d + 16);
    for (uint32_t s = 0; s < sizeof(wwe13_ps::kSheets) / sizeof(wwe13_ps::kSheets[0]); ++s) {
      const auto& sh = wwe13_ps::kSheets[s];
      if (w != sh.w || h != sh.h || at + 128 + w * h > size) continue;
      uint8_t* px = out + at + 128;
      if (Fnv(px, w * h) != sh.hash) continue;
      ApplyPatches(px, s, w);
      static int logged = 0;
      if (logged++ < 16) REXLOG_INFO("[wwe13-ps] {}x{} button icon sheet at guest 0x{:08X} -> PlayStation icons", w, h, guest + at);
    }
  }
}
}  // namespace

extern "C" PPC_FUNC(__imp__sub_82B29CA0);
extern "C" PPC_FUNC(sub_82B29CA0) {
  const uint32_t header = ctx.r3.u32, dest = ctx.r4.u32;
  __imp__sub_82B29CA0(ctx, base);
  if (!Enabled() || !header || !dest) return;
  const uint8_t* h = base + header;
  if (std::memcmp(h, "BPE ", 4) != 0) return;
  const uint32_t size = Le32(h + 12);
  if (size < 128 + 256 * 512 || size > (64u << 20)) return;
  PatchSheets(base + dest, size, dest);
}

// The other BPE path (sub_82B38500(dest, ?, header) -> sub_82B55E20): same header, output at dest.
extern "C" PPC_FUNC(__imp__sub_82B38500);
extern "C" PPC_FUNC(sub_82B38500) {
  const uint32_t dest = ctx.r3.u32, header = ctx.r5.u32;
  __imp__sub_82B38500(ctx, base);
  if (!Enabled() || !header || !dest) return;
  const uint8_t* h = base + header;
  const uint32_t size = Le32(h + 12);
  if (size < 128 + 256 * 512 || size > (64u << 20)) return;
  PatchSheets(base + dest, size, dest);
}
